"""
BRM Heart Simulator — сервер v2.0 (MQTT)
=========================================

    ESP32 ──MQTT──▶ Mosquitto ◀──MQTT── этот сервер ◀──WebSocket── браузер

Что делает:
  • Подключается к брокеру как `server` и слушает топики симуляторов:
        brm/+/status  online / offline (retained, Last Will)
        brm/+/tele    телеметрия: режим, BPM, PWM, оставшееся время, пароксизм...
        brm/+/ack     подтверждения команд START/STOP
        brm/+/event   boot / started / stopped / finished
        brm/+/pong    ответы на ping (меряем задержку)
        brm/+/set     сохранённая настройка (режим, минуты) — retained
  • Кнопки страницы:
        START  -> brm/<ID>/set (retained) + brm/<ID>/cmd {"id":N,"action":"start",...}
        STOP   -> brm/<ID>/cmd {"id":N,"action":"stop"}
        режим / минуты -> brm/<ID>/set (retained: ESP32 получит даже после перезагрузки)
    Каждая команда ждёт подтверждения ack с тем же номером. Нет ответа 4 с —
    на странице «нет ответа».
  • Таймер сеанса, логика мотора и режимов — на самой ESP32. Сервер только
    передаёт команды и показывает состояние. Пропал интернет — сеанс идёт дальше.

Страница — та же, что была на PythonAnywhere (v1.8): дизайн, ЭКГ, режимы, таймер.
Разница: данные приходят по WebSocket сразу, без опроса каждые 750 мс.

Настройки — переменные окружения (файл /opt/brm/brm.env):
    MQTT_HOST, MQTT_PORT, MQTT_USER, MQTT_PASS, WEB_USER, WEB_PASS, BRM_DEVICE
"""

import asyncio
import base64
import json
import logging
import os
import math
import urllib.request
import secrets
import time
from collections import deque
from contextlib import asynccontextmanager

import aiomqtt
from fastapi import Depends, FastAPI, HTTPException, WebSocket, WebSocketDisconnect, status
from fastapi.responses import HTMLResponse, Response
from fastapi.security import HTTPBasic, HTTPBasicCredentials

SERVER_VERSION = "2.0"

# ========================= НАСТРОЙКИ =========================
MQTT_HOST = os.environ.get("MQTT_HOST", "localhost")
MQTT_PORT = int(os.environ.get("MQTT_PORT", "1883"))
MQTT_USER = os.environ.get("MQTT_USER", "server")
MQTT_PASS = os.environ.get("MQTT_PASS", "")
WEB_USER = os.environ.get("WEB_USER", "brm")
WEB_PASS = os.environ.get("WEB_PASS", "")
PAGE_DEVICE = os.environ.get("BRM_DEVICE", "BRM001")   # какой симулятор показывает страница

PING_EVERY_SEC = 5
CMD_TIMEOUT_SEC = 4
RECONNECT_DELAY_SEC = 3

# Сценарии режимов: BPM вне сеанса и амплитуда ЭКГ (как в прошивке)
MODES = {
    "normal":      {"label": "Норма",                       "bpm": 76,  "amp": 60},
    "sinus_tachy": {"label": "Синусовая тахикардия",       "bpm": 120, "amp": 60},
    "parox_tachy": {"label": "Пароксизмальная тахикардия", "bpm": 76,  "amp": 65},
    "arrhythmia":  {"label": "Аритмия",                     "bpm": 90,  "amp": 65},
    "bradycardia": {"label": "Брадикардия",                 "bpm": 50,  "amp": 60},
}

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s", datefmt="%H:%M:%S")
log = logging.getLogger("brm")

# ========================= СОСТОЯНИЕ (в памяти) =========================
DEVICES: dict[str, dict] = {}
JOURNAL: deque = deque(maxlen=200)
PENDING_PINGS: dict[str, tuple[str, float]] = {}

mqtt_client: aiomqtt.Client | None = None
browsers: set[WebSocket] = set()
state_changed = asyncio.Event()
WS_TOKEN = secrets.token_urlsafe(16)
_last_cmd_id = 0


def device(dev_id: str) -> dict:
    return DEVICES.setdefault(dev_id, {
        "status": "unknown",          # online / offline / unknown
        "tele": {}, "tele_at": None,  # последняя телеметрия
        "config": {"mode": "normal", "minutes": 10},
        "rtt_ms": None,
        "cmd": None,                  # последняя команда: id, action, sent, state, ms
        "note": None,                 # текст для строки «КОМАНДА» на странице
        "fw": None, "boot_reason": None,
    })


def journal(dev_id: str, text: str) -> None:
    JOURNAL.appendleft({"t": time.strftime("%H:%M:%S"), "dev": dev_id, "text": text})
    log.info("[%s] %s", dev_id, text)
    state_changed.set()


def new_cmd_id() -> int:
    """Номер команды. Растёт всегда, даже после перезапуска сервера (основан на времени),
    чтобы ESP32 не приняла новую команду за повтор старой."""
    global _last_cmd_id
    _last_cmd_id = max(_last_cmd_id + 1, int(time.time() * 10) % 4_000_000_000)
    return _last_cmd_id


def parse_json(payload: str) -> dict:
    try:
        obj = json.loads(payload)
        return obj if isinstance(obj, dict) else {}
    except ValueError:
        return {}


# ========================= MQTT: приём =========================
def handle_message(msg: aiomqtt.Message) -> None:
    parts = str(msg.topic).split("/")
    if len(parts) != 3 or parts[0] != "brm":
        return
    _, dev_id, kind = parts
    payload = msg.payload.decode("utf-8", "replace") if isinstance(msg.payload, (bytes, bytearray)) else str(msg.payload)
    d = device(dev_id)

    if kind == "pong":
        sent = PENDING_PINGS.pop(payload, None)
        if sent:
            d["rtt_ms"] = round((time.monotonic() - sent[1]) * 1000)
            state_changed.set()

    elif kind == "status":
        if payload != d["status"]:
            journal(dev_id, f"ESP32 {payload}" + (" (сохранённый статус)" if msg.retain else ""))
        d["status"] = payload
        if payload != "online":
            d["rtt_ms"] = None

    elif kind == "tele":
        t = parse_json(payload)
        if t:
            d["tele"], d["tele_at"] = t, time.time()
            d["fw"] = t.get("fw", d["fw"])
            state_changed.set()

    elif kind == "set":
        cfg = parse_json(payload)
        if cfg.get("mode") in MODES:
            d["config"]["mode"] = cfg["mode"]
        if isinstance(cfg.get("minutes"), int):
            d["config"]["minutes"] = cfg["minutes"]
        state_changed.set()

    elif kind == "ack":
        a = parse_json(payload)
        c = d["cmd"]
        if c and a.get("id") == c["id"]:
            c["ms"] = round((time.monotonic() - c["sent"]) * 1000)
            c["state"] = "ok" if a.get("ok") else "fail"
            if c["state"] == "ok":
                d["note"] = (f"{c['action'].upper()} ✓ {c['ms']} мс", "ok")
            else:
                d["note"] = (f"{c['action'].upper()} ✗ {a.get('error', 'ошибка')}", "fail")
            journal(dev_id, f"подтверждение {c['action']} #{c['id']} за {c['ms']} мс")

    elif kind == "event":
        e = parse_json(payload)
        typ = e.get("type")
        if typ == "boot":
            d["boot_reason"] = e.get("reason")
            journal(dev_id, f"ESP32 загрузилась (причина: {e.get('reason')}, прошивка {e.get('fw')})")
        # Состояние «работает / остановлен» меняем сразу по событию,
        # не дожидаясь следующей телеметрии (в покое она идёт раз в 5 с).
        if typ in ("finished", "stopped"):
            d["tele"]["run"], d["tele"]["parox"] = 0, 0
        elif typ == "started":
            d["tele"]["run"] = 1
        if typ == "finished":
            d["note"] = ("сеанс завершён по таймеру", "ok")
            journal(dev_id, "сеанс завершён по таймеру")
        elif typ in ("started", "stopped"):
            journal(dev_id, f"сеанс {'запущен' if typ == 'started' else 'остановлен'}: "
                            f"{e.get('mode')}, {e.get('minutes')} мин")
    state_changed.set()


async def mqtt_worker() -> None:
    global mqtt_client
    while True:
        try:
            async with aiomqtt.Client(MQTT_HOST, MQTT_PORT, username=MQTT_USER, password=MQTT_PASS,
                                      identifier="brm-server", keepalive=30) as client:
                mqtt_client = client
                for topic, qos in (("brm/+/status", 1), ("brm/+/tele", 0), ("brm/+/ack", 1),
                                   ("brm/+/event", 1), ("brm/+/pong", 0), ("brm/+/set", 1)):
                    await client.subscribe(topic, qos=qos)
                journal("server", f"подключён к брокеру {MQTT_HOST}:{MQTT_PORT}")
                async for msg in client.messages:
                    handle_message(msg)
        except aiomqtt.MqttError as e:
            if mqtt_client is not None:
                journal("server", f"связь с брокером потеряна: {e}")
            mqtt_client = None
            state_changed.set()
            await asyncio.sleep(RECONNECT_DELAY_SEC)


async def publish(topic: str, payload: str, qos: int = 1, retain: bool = False) -> None:
    if mqtt_client is None:
        raise HTTPException(status.HTTP_503_SERVICE_UNAVAILABLE, "сервер не подключён к брокеру")
    await mqtt_client.publish(topic, payload, qos=qos, retain=retain)


# ========================= Фоновые задачи =========================
async def housekeeping() -> None:
    """Раз в секунду: таймауты команд; раз в 5 секунд: ping онлайн-устройств."""
    tick = 0
    while True:
        await asyncio.sleep(1)
        tick += 1
        now = time.monotonic()
        for dev_id, d in DEVICES.items():
            c = d["cmd"]
            if c and c["state"] == "pending" and now - c["sent"] > CMD_TIMEOUT_SEC:
                c["state"] = "fail"
                d["note"] = (f"{c['action'].upper()} ✗ нет ответа от ESP32", "fail")
                journal(dev_id, f"нет подтверждения {c['action']} #{c['id']}")
        if tick % PING_EVERY_SEC == 0 and mqtt_client is not None:
            for token, (_, t0) in list(PENDING_PINGS.items()):
                if now - t0 > 30:
                    PENDING_PINGS.pop(token, None)
            for dev_id, d in list(DEVICES.items()):
                if d["status"] == "online":
                    token = secrets.token_hex(4)
                    PENDING_PINGS[token] = (dev_id, time.monotonic())
                    try:
                        await publish(f"brm/{dev_id}/ping", token, qos=0)
                    except Exception:
                        pass


def page_state(dev_id: str) -> dict:
    """Состояние в том виде, который понимает страница (те же поля, что в v1.8)."""
    d = device(dev_id)
    online = mqtt_client is not None and d["status"] == "online"
    t = d["tele"] if online else {}
    cfg = d["config"]
    run = bool(t.get("run"))
    mode = t.get("mode") if t.get("mode") in MODES else cfg["mode"]
    note = d["note"]
    c = d["cmd"]
    if c and c["state"] == "pending":
        note = (f"{c['action'].upper()}… ждём ESP32", "pending")
    return {
        "practice": practice_view(dev_id),
        "esp32_ok": online,
        "mqtt": mqtt_client is not None,
        "run": run,
        "mode": mode,
        "mode_label": MODES[mode]["label"],
        "desired_mode": cfg["mode"],
        "session_minutes": cfg["minutes"],
        "target_bpm": t.get("bpm") if run else MODES[cfg["mode"]]["bpm"],
        "rpm": t.get("bpm", 0) if run else 0,
        "measured_bpm": t.get("bpm", 0) if run else 0,
        "motor_pwm": t.get("pwm", 0),
        "ui_amp": t.get("amp", MODES[mode]["amp"]),
        "time_left_sec": t.get("left", cfg["minutes"] * 60) if run else cfg["minutes"] * 60,
        "flags": t.get("flags", "0x00"),
        "paroxysm_active": bool(t.get("parox")) if run else False,
        "rtt_ms": d["rtt_ms"] if online else None,
        "cmd_text": note[0] if note else None,
        "cmd_state": note[1] if note else None,
        "fw": d["fw"],
    }


async def broadcaster() -> None:
    while True:
        await state_changed.wait()
        state_changed.clear()
        data = json.dumps(page_state(PAGE_DEVICE), ensure_ascii=False)
        for ws in list(browsers):
            try:
                await asyncio.wait_for(ws.send_text(data), timeout=2)
            except Exception:
                browsers.discard(ws)
        await asyncio.sleep(0.1)


# ========================= ВЕБ =========================
@asynccontextmanager
async def lifespan(app: FastAPI):
    if not MQTT_PASS or not WEB_PASS:
        raise RuntimeError("Не заданы MQTT_PASS / WEB_PASS — проверьте /opt/brm/brm.env")
    tasks = [asyncio.create_task(mqtt_worker()),
             asyncio.create_task(housekeeping()),
             asyncio.create_task(broadcaster())]
    log.info("BRM server v%s запущен, страница показывает %s", SERVER_VERSION, PAGE_DEVICE)
    yield
    for practice in PRACTICES.values():
        practice["task"].cancel()
    for t in tasks:
        t.cancel()


app = FastAPI(lifespan=lifespan, docs_url=None, redoc_url=None, openapi_url=None)
security = HTTPBasic()


def check_login(cred: HTTPBasicCredentials = Depends(security)) -> None:
    ok_user = secrets.compare_digest(cred.username.encode(), WEB_USER.encode())
    ok_pass = secrets.compare_digest(cred.password.encode(), WEB_PASS.encode())
    if not (ok_user and ok_pass):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Неверный логин или пароль",
                            headers={"WWW-Authenticate": "Basic"})


def check_device(dev_id: str) -> dict:
    if not dev_id.isalnum() or len(dev_id) > 24:
        raise HTTPException(400, "неверный ID устройства")
    return device(dev_id)


def check_mode_minutes(mode: str, minutes: int) -> None:
    if mode not in MODES:
        raise HTTPException(400, "неизвестный режим")
    if not 1 <= minutes <= 240:
        raise HTTPException(400, "время сеанса: от 1 до 240 минут")


@app.get("/", response_class=HTMLResponse, dependencies=[Depends(check_login)])
def index() -> HTMLResponse:
    return HTMLResponse(PAGE_HTML, headers={"Cache-Control": "no-store"})


@app.get("/app.js", dependencies=[Depends(check_login)])
def app_js() -> Response:
    js = APP_JS.replace("__DEVICE__", PAGE_DEVICE).replace("__WS_TOKEN__", WS_TOKEN)
    return Response(js, media_type="application/javascript", headers={"Cache-Control": "no-store"})


@app.get("/bg.jpg", dependencies=[Depends(check_login)])
def bg_jpg() -> Response:
    return Response(BG_JPG, media_type="image/jpeg", headers={"Cache-Control": "public, max-age=86400"})


@app.post("/api/{dev_id}/set", dependencies=[Depends(check_login)])
async def api_set(dev_id: str, mode: str = "normal", minutes: int = 10) -> dict:
    d = check_device(dev_id)
    if active_practice(dev_id):
        raise HTTPException(409, "Сначала остановите ИИ-сеанс.")
    check_mode_minutes(mode, minutes)
    await publish(f"brm/{dev_id}/set", json.dumps({"mode": mode, "minutes": minutes}), qos=1, retain=True)
    d["config"] = {"mode": mode, "minutes": minutes}
    state_changed.set()
    return {"ok": True}


def require_online(dev_id: str) -> dict:
    d = check_device(dev_id)
    if mqtt_client is None:
        raise HTTPException(503, "сервер не подключён к брокеру")
    if d["status"] != "online":
        raise HTTPException(409, "ESP32 не в сети")
    return d


async def send_cmd(dev_id: str, action: str, extra: dict | None = None) -> dict:
    d = require_online(dev_id)
    cmd_id = new_cmd_id()
    payload = {"id": cmd_id, "action": action, **(extra or {})}
    d["cmd"] = {"id": cmd_id, "action": action, "sent": time.monotonic(), "state": "pending", "ms": None}
    await publish(f"brm/{dev_id}/cmd", json.dumps(payload), qos=1)
    journal(dev_id, f"команда {action} #{cmd_id} отправлена")
    return {"ok": True, "id": cmd_id}


# ========================= СЛЕПАЯ ПРАКТИКА =========================
PRACTICE_MODE = "ai_practice"
PRACTICES: dict[str, dict] = {}
MANUAL_STARTS: set[str] = set()


def active_practice(dev_id: str) -> dict | None:
    practice = PRACTICES.get(dev_id)
    return practice if practice and practice["status"] in ("planning", "running", "stopping") else None


def practice_view(dev_id: str) -> dict | None:
    practice = PRACTICES.get(dev_id)
    if not practice:
        return None
    return {
        "id": practice["id"],
        "status": practice["status"],
        "minutes": practice["minutes"],
        "period": len(practice["played"]),
        "left": max(0, min(practice["minutes"] * 60,
            math.ceil(practice["deadline"] - time.monotonic()))) if practice["deadline"] else practice["minutes"] * 60,
        "error": practice.get("error"),
    }


def ask_practice(payload: dict) -> dict:
    request = urllib.request.Request(
        "http://127.0.0.1:8781/api/tutor",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(request, timeout=47) as response:
        return json.load(response)


async def wait_practice_ack(dev_id: str, command_id: int) -> None:
    deadline = time.monotonic() + CMD_TIMEOUT_SEC
    while time.monotonic() < deadline:
        command = require_online(dev_id)["cmd"]
        if command and command["id"] == command_id:
            if command["state"] == "ok":
                return
            if command["state"] == "fail":
                break
        await asyncio.sleep(0.1)
    raise RuntimeError("ESP32 не подтвердила команду.")


async def practice_worker(dev_id: str, practice: dict) -> None:
    may_be_running = False
    try:
        modes = list(MODES)
        secrets.SystemRandom().shuffle(modes)
        result = await asyncio.to_thread(ask_practice, {
            "practice": "plan", "minutes": practice["minutes"], "modes": modes,
            "seed": secrets.token_hex(8),
        })
        plan = result.get("plan")
        if (not isinstance(plan, list) or not 1 <= len(plan) <= practice["minutes"]
                or any(not isinstance(mode, str) or mode not in MODES for mode in plan)
                or any(a == b for a, b in zip(plan, plan[1:]))):
            raise RuntimeError("ИИ не вернул допустимое расписание. Повторите START.")
        require_online(dev_id)
        if page_state(dev_id)["run"]:
            raise RuntimeError("Сначала остановите текущий сеанс.")
        practice["minutes"] = len(plan)
        practice["status"] = "running"
        started = time.monotonic()
        practice["deadline"] = started + len(plan) * 60
        for index, mode in enumerate(plan, start=1):
            may_be_running = True
            command = await asyncio.wait_for(send_cmd(dev_id, "start", {"mode": mode, "minutes": 1}), timeout=5)
            await wait_practice_ack(dev_id, command["id"])
            practice["played"].append(mode)
            segment_end = started + index * 60
            state_changed.set()
            while time.monotonic() < segment_end:
                require_online(dev_id)
                await asyncio.sleep(min(1, max(0, segment_end - time.monotonic())))
                state_changed.set()
        command = await asyncio.wait_for(send_cmd(dev_id, "stop"), timeout=5)
        await wait_practice_ack(dev_id, command["id"])
        practice["status"] = "complete"
    except asyncio.CancelledError:
        raise
    except Exception as error:
        practice["status"] = "stopping" if may_be_running else "error"
        practice["error"] = str(error) if isinstance(error, RuntimeError) else "Не удалось продолжить ИИ-сеанс. Проверьте связь со стендом и повторите START."
        if may_be_running:
            try:
                command = await asyncio.wait_for(send_cmd(dev_id, "stop"), timeout=5)
                await wait_practice_ack(dev_id, command["id"])
            except Exception:
                practice["error"] += " STOP не подтверждён. Проверьте стенд."
            practice["status"] = "error"
    finally:
        state_changed.set()


def begin_practice(dev_id: str, minutes: int) -> dict:
    d = require_online(dev_id)
    if not 1 <= minutes <= 20:
        raise HTTPException(400, "ИИ-практика: от 1 до 20 минут.")
    if dev_id in MANUAL_STARTS or page_state(dev_id)["run"] or (d["cmd"] and d["cmd"]["state"] == "pending"):
        raise HTTPException(409, "Дождитесь остановки текущего сеанса.")
    practice = {"id": secrets.token_urlsafe(18), "status": "planning", "minutes": minutes,
                "played": [], "deadline": None}
    PRACTICES[dev_id] = practice
    practice["task"] = asyncio.create_task(practice_worker(dev_id, practice))
    state_changed.set()
    return {"ok": True}


@app.post("/api/{dev_id}/practice-review", dependencies=[Depends(check_login)])
async def api_practice_review(dev_id: str, review: dict) -> dict:
    check_device(dev_id)
    practice = PRACTICES.get(dev_id)
    if not practice or practice["id"] != review.get("id") or practice["status"] != "complete":
        raise HTTPException(409, "Разбор доступен после завершения текущего сеанса.")
    guesses = review.get("guesses")
    if (not isinstance(guesses, list) or len(guesses) != len(practice["played"])
            or any(not isinstance(mode, str) or mode not in MODES for mode in guesses)):
        raise HTTPException(400, "Выберите ритм для каждой минуты.")
    rows = [
        {"minute": index, "expected": MODES[actual]["label"], "chosen": MODES[guess]["label"],
         "correct": actual == guess}
        for index, (actual, guess) in enumerate(zip(practice["played"], guesses), start=1)
    ]
    try:
        result = await asyncio.to_thread(ask_practice, {"practice": "review", "rows": rows})
    except Exception:
        return {"rows": rows, "feedback": None}
    return {"rows": rows, **result}


@app.post("/api/{dev_id}/start", dependencies=[Depends(check_login)])
async def api_start(dev_id: str, mode: str = "normal", minutes: int = 10) -> dict:
    if active_practice(dev_id) or dev_id in MANUAL_STARTS:
        raise HTTPException(409, "Запуск уже выполняется.")
    if mode == PRACTICE_MODE:
        return begin_practice(dev_id, minutes)
    check_mode_minutes(mode, minutes)
    require_online(dev_id)                            # сначала проверка: отклонённый START ничего не меняет
    MANUAL_STARTS.add(dev_id)
    try:
        await api_set(dev_id, mode, minutes)
        return await send_cmd(dev_id, "start", {"mode": mode, "minutes": minutes})
    finally:
        MANUAL_STARTS.discard(dev_id)


@app.post("/api/{dev_id}/stop", dependencies=[Depends(check_login)])
async def api_stop(dev_id: str) -> dict:
    practice = active_practice(dev_id)
    if not practice:
        return await send_cmd(dev_id, "stop")
    if practice["status"] == "stopping":
        return {"ok": True}
    practice["status"] = "stopping"
    practice["task"].cancel()
    state_changed.set()
    try:
        await asyncio.gather(practice["task"], return_exceptions=True)
        command = await asyncio.wait_for(send_cmd(dev_id, "stop"), timeout=5)
        await wait_practice_ack(dev_id, command["id"])
        practice["status"] = "cancelled"
        return command
    except Exception as error:
        practice["status"] = "error"
        practice["error"] = "STOP не подтверждён. Проверьте стенд."
        raise HTTPException(503, practice["error"]) from error
    finally:
        state_changed.set()


@app.get("/api/{dev_id}/state", dependencies=[Depends(check_login)])
def api_state(dev_id: str) -> dict:
    check_device(dev_id)
    return page_state(dev_id)


@app.get("/api/journal", dependencies=[Depends(check_login)])
def api_journal() -> list:
    return list(JOURNAL)


@app.get("/health")
def health() -> dict:
    return {"version": SERVER_VERSION, "mqtt_connected": mqtt_client is not None, "devices": len(DEVICES)}


@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket) -> None:
    await ws.accept()                                   # сначала accept, иначе браузер не увидит код 4401
    if ws.query_params.get("token") != WS_TOKEN:
        await ws.close(code=4401)
        return
    browsers.add(ws)
    try:
        await ws.send_text(json.dumps(page_state(PAGE_DEVICE), ensure_ascii=False))
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        pass
    finally:
        browsers.discard(ws)


